import{_ as a,a as t,b as r,c as i,d as n,e as o,f as l,g as s,h as u,i as c,j as p,k as d}from"./chunks/101-10.abiX99wn.js";import{_ as m,o as g,c as b,a3 as h}from"./chunks/framework.g9mfNVRQ.js";const D=JSON.parse(`{"title":"Bases de l'étalonnage","description":"","frontmatter":{"source_hash":"2ab418e8fa","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/calibrate/101.md","filePath":"fr/calibrate/101.md"}`),f={name:"fr/calibrate/101.md"};function v(q,e,_,y,x,z){return g(),b("div",null,[...e[0]||(e[0]=[h('<h3 id="about-calibration" tabindex="-1">À propos de l&#39;étalonnage <a class="header-anchor" href="#about-calibration" aria-label="Permalink to &quot;À propos de l&#39;étalonnage {#about-calibration}&quot;">​</a></h3><h4 id="how-do-sensors-work" tabindex="-1">Comment fonctionnent les capteurs ? <a class="header-anchor" href="#how-do-sensors-work" aria-label="Permalink to &quot;Comment fonctionnent les capteurs ? {#how-do-sensors-work}&quot;">​</a></h4><p>Les capteurs de glucose génèrent un signal électrique à partir d&#39;une réaction chimique avec la concentration de glucose du liquide interstitiel ; dans xDrip, on l&#39;appelle généralement donnée brute (raw).<br><strong>Cette valeur n&#39;est pas directement utilisable comme mesure de glycémie.</strong></p><img src="'+a+'" style="zoom:75%;"><p>Il existe un « <a href="https://pubmed.ncbi.nlm.nih.gov/20920428/" target="_blank" rel="noreferrer">retard</a> » physiologique entre la glycémie capillaire et la concentration de glucose interstitiel, et les deux tendent à devenir proportionnelles au bout d&#39;un certain temps. On considère que 10 minutes à <strong>glycémie stable</strong> sont un délai raisonnable pour réduire l&#39;imprécision.</p><img src="'+t+'" style="zoom:75%;"><p>Pour utiliser les données brutes comme équivalent de la glycémie, vous devez leur donner une référence. À moins que le capteur ne dispose d&#39;un calcul de calibration natif (aussi appelé calibration d&#39;usine), elles ne correspondront <strong><a href="https://www.liebertpub.com/doi/10.1089/dia.2016.0112" target="_blank" rel="noreferrer">pas</a></strong> à la glycémie réelle.</p><br><h4 id="proprietary-calibration-algorithms" tabindex="-1">Algorithmes de calibration propriétaires <a class="header-anchor" href="#proprietary-calibration-algorithms" aria-label="Permalink to &quot;Algorithmes de calibration propriétaires {#proprietary-calibration-algorithms}&quot;">​</a></h4><p>Certains fabricants proposent des capteurs calibrés en usine (G6 et Libre) qui peuvent ne pas atteindre la précision attendue. Le premier permet d&#39;appliquer une calibration en mode natif, tandis que le second ne peut pas être étalonné avec l&#39;application du fabricant.</p><br><h4 id="native-mode-calibration" tabindex="-1">Calibration en mode natif <a class="header-anchor" href="#native-mode-calibration" aria-label="Permalink to &quot;Calibration en mode natif {#native-mode-calibration}&quot;">​</a></h4><p>Les capteurs G6, G7, ONE, ONE+ et Stelo sont calibrés en usine : vous saisissez le code de calibration ou le code du capteur au démarrage. Si vous souhaitez étalonner, xDrip se contente d&#39;envoyer les données de calibration à l&#39;émetteur du capteur pour qu&#39;il les traite : il n&#39;applique aucun algorithme local. En mode natif, xDrip s&#39;appuie sur les données de l&#39;émetteur, c&#39;est pourquoi votre récepteur (si vous en avez un) affiche les mêmes données.</p><p>Plus d&#39;informations <a href="https://navid200.github.io/xDrip/docs/Calibrate-G6.html" target="_blank" rel="noreferrer">ici</a>.</p><br><h3 id="when-calibrating-is-dangerous" tabindex="-1">Quand l&#39;étalonnage est dangereux <a class="header-anchor" href="#when-calibrating-is-dangerous" aria-label="Permalink to &quot;Quand l&#39;étalonnage est dangereux {#when-calibrating-is-dangerous}&quot;">​</a></h3><p>Étalonner lorsque la glycémie n&#39;est pas stable produit de mauvaises calibrations, et donc des données de glycémie erronées auxquelles vous ne pouvez pas vous fier.<br> Étalonner lorsque la courbe de glycémie est plate est extrêmement dangereux : cela signifie que votre capteur est hors plage ou défaillant, et que les données brutes ne représentent plus du tout la glycémie.</p><img src="'+r+'" style="zoom:75%;"><img src="'+i+'" style="zoom:75%;"><br><h3 id="xdrip-calibration-algorithm" tabindex="-1">Algorithme de calibration de xDrip <a class="header-anchor" href="#xdrip-calibration-algorithm" aria-label="Permalink to &quot;Algorithme de calibration de xDrip {#xdrip-calibration-algorithm}&quot;">​</a></h3><h4 id="intercept" tabindex="-1">Ordonnée à l&#39;origine (intercept) <a class="header-anchor" href="#intercept" aria-label="Permalink to &quot;Ordonnée à l&#39;origine (intercept) {#intercept}&quot;">​</a></h4><p>Si vous mesurez votre glycémie avec un lecteur de glycémie qui affiche 100 mg/dl de façon stable et que, 10 minutes plus tard, votre CGM indique 130, vous voudrez étalonner. C&#39;est ainsi que vous indiquez à xDrip qu&#39;une valeur brute de 130 correspond à une valeur réelle de 100.</p><p>Étalonner dans ces conditions donne un graphique de calibration qui ressemble, en théorie, à ceci :</p><img src="'+n+'" style="zoom:75%;"><p>Ce qui se traduit ainsi : la glycémie étalonnée sera égale à la valeur brute moins 30.</p><p>-30 est appelé l&#39;<strong>ordonnée à l&#39;origine</strong> (intercept), c&#39;est-à-dire un <strong>décalage</strong> (offset) entre la valeur brute et la glycémie étalonnée.<br> L&#39;ordonnée à l&#39;origine pèse davantage sur les mesures de glycémie basses : il est recommandé qu&#39;elle soit la plus précise possible pour que xDrip soit précis dans la plage basse, celle qui compte pour votre sécurité.</p><p><strong>Effectuez le premier étalonnage du capteur avec une glycémie stable dans le bas de la plage normale (90 à 120 mg/dl - 5 à 7 mmol/l)</strong>.</p><p>La valeur de l&#39;ordonnée à l&#39;origine déplace votre glycémie étalonnée vers le haut ou vers le bas.</p><img src="'+o+'" style="zoom:75%;"><br><h4 id="slope" tabindex="-1">Pente (slope) <a class="header-anchor" href="#slope" aria-label="Permalink to &quot;Pente (slope) {#slope}&quot;">​</a></h4><p>Avec la calibration ci-dessus, les valeurs peuvent être imprécises lorsque la valeur brute est très différente... par exemple xDrip affichera 170 mg/dl et votre lecteur de glycémie 205 mg/dl. Dans ce cas, le décalage est différent pour les glycémies plus hautes... c&#39;est la valeur brute plus 5...</p><img src="'+l+'" style="zoom:75%;"><p>Pour que xDrip soit précis dans cette plage de glycémie, vous devez ajouter un autre point de calibration. Une fois cela fait, votre courbe se modifie en théorie ainsi :</p><img src="'+s+'" style="zoom:75%;"><p>Vous voyez que la ligne rouge est plus raide et que le paramètre de pente a augmenté. Ici, une pente de 1,5 signifie qu&#39;une petite variation de la valeur brute entraîne une plus grande variation de la glycémie affichée par xDrip.<br> La pente pèse davantage sur les mesures de glycémie hautes : si vous avez besoin de précision sur les glycémies élevées, ajoutez un point de calibration dans la plage haute.</p><p><strong>Ajoutez une valeur de calibration plus haute, à glycémie stable, dans le haut de la plage normale ; n&#39;étalonnez pas avec une glycémie trop élevée (180 à 220 mg/dl - 10 à 12 mmol/l).</strong></p><p>Cette <strong>pente</strong> est un coefficient qui <strong>multiplie</strong> la valeur brute, comparable à un <strong>gain</strong>. Elle augmente ou diminue la sensibilité de la glycémie aux données brutes.</p><img src="'+u+'" style="zoom:75%;"><br><h4 id="maths-models-and-real-life" tabindex="-1">Mathématiques, modèles et vie réelle <a class="header-anchor" href="#maths-models-and-real-life" aria-label="Permalink to &quot;Mathématiques, modèles et vie réelle {#maths-models-and-real-life}&quot;">​</a></h4><p>Votre courbe de calibration est le résultat d&#39;un calcul mathématique qui cherche la droite s&#39;ajustant le mieux à tous les points de calibration fournis, en minimisant la distance entre chaque point et la droite théorique.</p><img src="'+c+'" style="zoom:75%;"><p>Sa qualité dépend de votre capteur et de votre stratégie d&#39;étalonnage.<br> Si votre capteur est bruité ou si vous n&#39;étalonnez pas à glycémie stable, l&#39;algorithme aura du mal à ajuster toutes les données et produira une courbe de calibration imprécise : impossible de faire passer une droite près de tous les points d&#39;un nuage de calibrations.</p><img src="'+p+'" style="zoom:75%;"><br><h4 id="interstitial-delay" tabindex="-1">« Retard » interstitiel <a class="header-anchor" href="#interstitial-delay" aria-label="Permalink to &quot;« Retard » interstitiel {#interstitial-delay}&quot;">​</a></h4><p>C&#39;est probablement le facteur le plus complexe à prendre en compte lors d&#39;un étalonnage, et c&#39;est pourquoi une glycémie stable est essentielle.</p><p>Il existe un retard entre la glycémie capillaire et la concentration de glucose du liquide interstitiel ; d&#39;autres paramètres, comme l&#39;activité physique, les font aussi évoluer différemment...</p><p>Comme xDrip ne peut ni connaître ni deviner ce retard, étalonner avec une glycémie qui varie rapidement ne fonctionnera pas.</p><img src="'+d+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 7/12/2024</em></a></p>',54)])])}const C=m(f,[["render",v]]);export{D as __pageData,C as default};
